1	import bcrypt from "bcryptjs";
2	import { cookies } from "next/headers";
3	import { LoginSchema, RegisterSchema } from "@/lib/validations";
4	import { prisma } from "@/lib/prisma";
5	
6	export async function registerUser(rawInput: unknown) {
7	  const parseResult = RegisterSchema.safeParse(rawInput);
8	  if (!parseResult.success) {
9	    throw new Error(parseResult.error.issues.map((issue) => issue.message).join(", "));
10	  }
11	
12	  const { fullName, email, password, phone } = parseResult.data;
13	
14	  const existingUser = await prisma.user.findUnique({ where: { email } });
15	  if (existingUser) {
16	    throw new Error("Cet email est déjà utilisé par un autre compte");
17	  }
18	
19	  const passwordHash = await bcrypt.hash(password, 10);
20	
21	  const user = await prisma.user.create({
22	    data: {
23	      fullName,
24	      email,
25	      passwordHash,
26	      phone: phone || null,
27	      role: "CUSTOMER",
28	    },
29	  });
30	
31	  return createSession(user.id);
32	}
33	
34	export async function loginUser(rawInput: unknown) {
35	  const parseResult = LoginSchema.safeParse(rawInput);
36	  if (!parseResult.success) {
37	    throw new Error(parseResult.error.issues.map((issue) => issue.message).join(", "));
38	  }
39	
40	  const { email, password } = parseResult.data;
41	
42	  const user = await prisma.user.findUnique({ where: { email } });
43	  if (!user) {
44	    throw new Error("Email ou mot de passe incorrect");
45	  }
46	
47	  const isValidPassword = await bcrypt.compare(password, user.passwordHash);
48	  if (!isValidPassword) {
49	    throw new Error("Email ou mot de passe incorrect");
50	  }
51	
52	  return createSession(user.id);
53	}
54	
55	async function createSession(userId: string) {
56	  const token = bcrypt.hashSync(userId + Date.now().toString(), 5).replace(/[/\\?%*:|"<>]/g, "");
57	  const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days
58	
59	  const session = await prisma.session.create({
60	    data: {
61	      userId,
62	      token,
63	      expiresAt,
64	    },
65	    include: { user: true },
66	  });
67	
68	  const cookieStore = await cookies();
69	  cookieStore.set({
70	    name: "session_token",
71	    value: token,
72	    httpOnly: true,
73	    secure: process.env.NODE_ENV === "production",
74	    sameSite: "lax",
75	    expires: expiresAt,
76	    path: "/",
77	  });
78	
79	  return session.user;
80	}
81	
82	export async function getCurrentUser() {
83	  const cookieStore = await cookies();
84	  const token = cookieStore.get("session_token")?.value;
85	
86	  if (!token) return null;
87	
88	  const session = await prisma.session.findUnique({
89	    where: { token },
90	    include: { user: true },
91	  });
92	
93	  if (!session || session.expiresAt < new Date()) {
94	    return null;
95	  }
96	
97	  return session.user;
98	}
99	
100	export async function logoutUser() {
101	  const cookieStore = await cookies();
102	  const token = cookieStore.get("session_token")?.value;
103	
104	  if (token) {
105	    await prisma.session.delete({ where: { token } }).catch(() => {});
106	  }
107	
108	  cookieStore.delete("session_token");
109	}
