1	import { cookies } from "next/headers";
2	import { NextResponse } from "next/server";
3	import { createOrder } from "@/lib/orders";
4	import { CART_SESSION_COOKIE } from "@/lib/cart-session";
5	
6	export async function POST(request: Request) {
7	  const sessionId = (await cookies()).get(CART_SESSION_COOKIE)?.value;
8	  if (!sessionId) return NextResponse.json({ error: "Votre panier est vide." }, { status: 400 });
9	
10	  const input = await request.json().catch(() => null);
11	  try {
12	    const order = await createOrder(sessionId, input);
13	    return NextResponse.json({ orderNumber: order.orderNumber }, { status: 201 });
14	  } catch (error) {
15	    const message = error instanceof Error ? error.message : "Impossible de créer la commande.";
16	    return NextResponse.json({ error: message }, { status: 400 });
17	  }
18	}
