1	import { randomUUID } from "node:crypto";
2	import { cookies } from "next/headers";
3	import { NextResponse } from "next/server";
4	import { z } from "zod";
5	import { addToCart, getOrCreateCart, serializeCart } from "@/lib/cart";
6	import { CART_SESSION_COOKIE } from "@/lib/cart-session";
7	import { prisma } from "@/lib/prisma";
8	import { CartItemInputSchema } from "@/lib/validations";
9	
10	const sessionSchema = z.string().uuid();
11	
12	async function getSessionId() {
13	  const jar = await cookies();
14	  const value = jar.get(CART_SESSION_COOKIE)?.value;
15	  const parsed = sessionSchema.safeParse(value);
16	  return { jar, sessionId: parsed.success ? parsed.data : randomUUID(), isNew: !parsed.success };
17	}
18	
19	function applySessionCookie(response: NextResponse, sessionId: string, isNew: boolean) {
20	  if (isNew) {
21	    response.cookies.set(CART_SESSION_COOKIE, sessionId, {
22	      httpOnly: true,
23	      secure: process.env.NODE_ENV === "production",
24	      sameSite: "lax",
25	      path: "/",
26	      maxAge: 60 * 60 * 24 * 30,
27	    });
28	  }
29	  return response;
30	}
31	
32	export async function GET() {
33	  const { sessionId, isNew } = await getSessionId();
34	  const cart = await getOrCreateCart(sessionId);
35	  return applySessionCookie(NextResponse.json(serializeCart(cart)), sessionId, isNew);
36	}
37	
38	export async function POST(request: Request) {
39	  const body = await request.json().catch(() => null);
40	  const parsed = CartItemInputSchema.safeParse(body);
41	  if (!parsed.success) {
42	    return NextResponse.json({ error: "Données de panier invalides." }, { status: 400 });
43	  }
44	
45	  const { sessionId, isNew } = await getSessionId();
46	  const variant = await prisma.productVariant.findUnique({
47	    where: { sku: parsed.data.variantSku },
48	    include: { product: { select: { isActive: true } } },
49	  });
50	  if (!variant || !variant.product.isActive) {
51	    return NextResponse.json({ error: "Ce produit n'est plus disponible." }, { status: 404 });
52	  }
53	
54	  try {
55	    const cart = await addToCart(sessionId, variant.id, parsed.data.quantity);
56	    return applySessionCookie(NextResponse.json(serializeCart(cart)), sessionId, isNew);
57	  } catch (error) {
58	    const message = error instanceof Error ? error.message : "Impossible de mettre à jour le panier.";
59	    return NextResponse.json({ error: message }, { status: 409 });
60	  }
61	}
62	
63	
