1	import { cookies } from "next/headers";
2	import { NextResponse } from "next/server";
3	import { z } from "zod";
4	import { removeCartItem, serializeCart, updateCartItemQuantity } from "@/lib/cart";
5	import { CART_SESSION_COOKIE } from "@/lib/cart-session";
6	
7	const quantitySchema = z.object({ quantity: z.number().int().min(1).max(99) });
8	
9	async function getSessionId() {
10	  const value = (await cookies()).get(CART_SESSION_COOKIE)?.value;
11	  return z.string().uuid().safeParse(value).success ? value : null;
12	}
13	
14	export async function PATCH(request: Request, context: RouteContext<"/api/cart/[itemId]">) {
15	  const sessionId = await getSessionId();
16	  if (!sessionId) return NextResponse.json({ error: "Panier introuvable." }, { status: 404 });
17	  const parsed = quantitySchema.safeParse(await request.json().catch(() => null));
18	  if (!parsed.success) return NextResponse.json({ error: "Quantité invalide." }, { status: 400 });
19	  const { itemId } = await context.params;
20	  try {
21	    const cart = await updateCartItemQuantity(sessionId, itemId, parsed.data.quantity);
22	    return NextResponse.json(serializeCart(cart));
23	  } catch (error) {
24	    const message = error instanceof Error ? error.message : "Impossible de modifier le panier.";
25	    return NextResponse.json({ error: message }, { status: 409 });
26	  }
27	}
28	
29	export async function DELETE(_request: Request, context: RouteContext<"/api/cart/[itemId]">) {
30	  const sessionId = await getSessionId();
31	  if (!sessionId) return NextResponse.json({ error: "Panier introuvable." }, { status: 404 });
32	  const { itemId } = await context.params;
33	  try {
34	    const cart = await removeCartItem(sessionId, itemId);
35	    return NextResponse.json(serializeCart(cart));
36	  } catch (error) {
37	    const message = error instanceof Error ? error.message : "Impossible de modifier le panier.";
38	    return NextResponse.json({ error: message }, { status: 409 });
39	  }
40	}
