2	import { loginUser } from "@/lib/auth";
3	import { prisma } from "@/lib/prisma";
4	
5	export async function POST(request: Request) {
6	  try {
7	    const body = await request.json();
8	    const user = await loginUser(body);
9	
10	    if (user.role !== "ADMIN") {
11	      return NextResponse.json({ error: "Accès refusé. Privilèges administrateur requis." }, { status: 403 });
12	    }
13	
14	    return NextResponse.json({ success: true, user: { email: user.email, fullName: user.fullName } });
15	  } catch (error) {
16	    const message = error instanceof Error ? error.message : "Erreur de connexion";
17	    return NextResponse.json({ error: message }, { status: 401 });
18	  }
19	}

