5	    where: { sessionId },
6	    create: { sessionId },
7	    update: {},
8	    include: {
9	      items: {
10	        include: {
11	          variant: {
12	            include: {
13	              product: {
14	                include: { images: true },
15	              },
16	            },
17	          },
18	        },
19	      },
20	    },
