24	export async function addToCart(sessionId: string, variantId: string, quantity: number) {
25	  const cart = await getOrCreateCart(sessionId);
26	
27	  const variant = await prisma.productVariant.findUnique({
28	    where: { id: variantId },
29	  });
30	
31	  if (!variant || variant.stock < quantity) {
32	    throw new Error("Stock insuffisant pour ce produit");
33	  }
34	
35	  const existingItem = cart.items.find((item) => item.variantId === variantId);
36	
37	  if (existingItem) {
38	    const newQuantity = existingItem.quantity + quantity;
39	    if (variant.stock < newQuantity) {
40	      throw new Error("Stock insuffisant pour la quantité demandée");
41	    }
42	
43	    await prisma.cartItem.update({
44	      where: { id: existingItem.id },
45	      data: { quantity: newQuantity },
46	    });
47	  } else {
48	    await prisma.cartItem.create({
49	      data: {
50	        cartId: cart.id,
51	        variantId,
52	        quantity,
53	      },
54	    });
55	  }
56	
57	  return getOrCreateCart(sessionId);
58	}
