60	export async function updateCartItemQuantity(sessionId: string, itemId: string, quantity: number) {
61	  const item = await prisma.cartItem.findUnique({
62	    where: { id: itemId },
63	    include: { variant: true, cart: true },
64	  });
65	
66	  if (!item || item.cart.sessionId !== sessionId) {
67	    throw new Error("Article introuvable dans le panier");
68	  }
69	
70	  if (quantity <= 0) {
71	    await prisma.cartItem.delete({ where: { id: itemId } });
72	  } else {
73	    if (item.variant.stock < quantity) {
74	      throw new Error("Stock insuffisant");
75	    }
76	    await prisma.cartItem.update({
77	      where: { id: itemId },
78	      data: { quantity },
79	    });
80	  }
81	
82	  return getOrCreateCart(sessionId);
83	}
