85	export async function removeCartItem(sessionId: string, itemId: string) {
86	  const item = await prisma.cartItem.findUnique({
87	    where: { id: itemId },
88	    include: { cart: true },
89	  });
90	
91	  if (!item || item.cart.sessionId !== sessionId) {
92	    throw new Error("Article introuvable dans le panier");
93	  }
94	
95	  await prisma.cartItem.delete({ where: { id: itemId } });
96	  return getOrCreateCart(sessionId);
