99	type PriceValue = number | { toNumber(): number };
100	
101	export function computeCartTotals(cart: {
102	  items: Array<{ quantity: number; variant: { price: PriceValue | null; product: { price: PriceValue } } }>;
103	}) {
104	  let subtotal = 0;
105	
106	  for (const item of cart.items) {
107	    const price = Number(item.variant.price ?? item.variant.product.price);
108	    subtotal += price * item.quantity;
109	  }
110	
111	  // Free shipping threshold in Morocco e.g. 500 MAD, otherwise 30 MAD delivery fee
112	  const shippingCost = subtotal >= 500 || subtotal === 0 ? 0 : 30;
113	  const total = subtotal + shippingCost;
114	
115	  return {
116	    subtotal,
117	    shippingCost,
118	    total,
119	  };
120	}
121	
122	export function serializeCart(cart: Awaited<ReturnType<typeof getOrCreateCart>>) {
123	  const items = cart.items.map((item) => {
124	    const unitPrice = Number(item.variant.price ?? item.variant.product.price);
125	    return {
126	      id: item.id,
127	      title: item.variant.product.titleFr,
128	      variantName: item.variant.nameFr,
129	      variantId: item.variantId,
130	      quantity: item.quantity,
131	      unitPrice,
132	      lineTotal: unitPrice * item.quantity,
133	      image: item.variant.product.images[0]?.url ?? null,
134	    };
135	  });
136	  const totals = computeCartTotals(cart);
137	  return { items, ...totals };
138	}
