1	import crypto from "crypto";
2	
3	// Simulated CMI (Centre Monétaire Interbancaire) or credit card gateway webhook verification
4	// In production, verify HMAC signature or gateway payload token.
5	export function verifyPaymentWebhook(payload: string, signature: string, secret: string): boolean {
6	  const hmac = crypto.createHmac("sha256", secret);
7	  const digest = hmac.update(payload).digest("hex");
8	  const expected = Buffer.from(digest, "hex");
9	  const received = Buffer.from(signature, "hex");
10	  return received.length === expected.length && crypto.timingSafeEqual(expected, received);
11	}
