12	export async function handlePaymentWebhook(rawBody: string, signature: string) {
13	  const configuredSecret = process.env.PAYMENT_WEBHOOK_SECRET;
14	  if (process.env.NODE_ENV === "production" && !configuredSecret) {
15	    throw new Error("PAYMENT_WEBHOOK_SECRET doit être configuré en production");
16	  }
17	  const webhookSecret = configuredSecret ?? "development-secret";
18	
19	  // 1. Verify cryptographic signature for security
20	  const isValid = verifyPaymentWebhook(rawBody, signature, webhookSecret);
21	  if (!isValid) {
22	    throw new Error("Signature de webhook invalide");
23	  }
24	
25	  let body: unknown;
26	  try {
27	    body = JSON.parse(rawBody);
28	  } catch {
29	    throw new Error("Payload de webhook invalide");
30	  }
31	  const parsedEvent = webhookEventSchema.safeParse(body);
32	  if (!parsedEvent.success) {
33	    throw new Error("Payload de webhook invalide");
34	  }
35	
36	  const { orderNumber, status, failureReason } = parsedEvent.data;
37	
38	  // 2. Find order
39	  const order = await prisma.order.findUnique({
40	    where: { orderNumber },
41	    include: { items: { include: { variant: true } } },
42	  });
43	
44	  if (!order) {
45	    throw new Error(`Commande introuvable: ${orderNumber}`);
46	  }
47	
48	  // Idempotency check: if already paid or cancelled, don't re-process
49	  if (order.paymentStatus === "PAID" && status === "SUCCESS") {
50	    return { success: true, message: "Paiement déjà validé (idempotent)" };
51	  }
52	
53	  let newPaymentStatus: PaymentStatus = order.paymentStatus;
54	  let newOrderStatus: OrderStatus = order.status;
55	
56	  if (status === "SUCCESS") {
57	    newPaymentStatus = "PAID";
58	    newOrderStatus = "CONFIRMED";
59	  } else if (status === "FAILED") {
60	    newPaymentStatus = "FAILED";
61	    newOrderStatus = "PENDING"; // Keep pending so customer can retry payment
62	  } else if (status === "RETRY") {
63	    newPaymentStatus = "PENDING";
64	    newOrderStatus = "PENDING";
65	  }
66	
67	  // 3. Update order and restock if failed permanently (optional based on policy)
68	  const updatedOrder = await prisma.$transaction(async (tx) => {
69	    // If payment failed and was previously pending, we record failure
70	    const updated = await tx.order.update({
71	      where: { id: order.id },
72	      data: {
73	        paymentStatus: newPaymentStatus,
74	        status: newOrderStatus,
75	        notes: failureReason ? `Échec paiement: ${failureReason}` : order.notes,
76	      },
77	    });
78	
79	    // If payment failed permanently and items were deducted, handle stock return if needed
80	    if (status === "FAILED" && order.paymentStatus === "PENDING") {
81	      // Optional: Log payment failure audit event
82	    }
83	
84	    return updated;
85	  });
86	
87	  return {
88	    success: true,
89	    orderNumber: updatedOrder.orderNumber,
90	    paymentStatus: updatedOrder.paymentStatus,
91	    orderStatus: updatedOrder.status,
92	  };
93	}
