21	        method: "POST",
22	        headers: { "Content-Type": "application/json" },
23	        body: JSON.stringify({ email, password }),
24	      });
25	
26	      const data = await response.json();
27	      if (!response.ok) {
28	        throw new Error(data.error || "Identifiants incorrects");
29	      }
30	
31	      router.push("/admin");
32	      router.refresh();
33	    } catch (err) {
34	      setError(err instanceof Error ? err.message : "Erreur de connexion");
35	    } finally {
36	      setLoading(false);
37	    }
38	  }
39	
40	  return (
