50	
51	        {error && (
52	          <div className="bg-red-500/10 border border-red-500/20 text-red-400 text-xs p-3.5 rounded-xl flex items-center gap-2" role="alert">
53	            <AlertCircle className="w-4 h-4 shrink-0" />
54	            <span>{error}</span>
55	          </div>
56	        )}
57	
58	        <form onSubmit={handleLogin} className="space-y-4">
