69	              />
70	              <Mail className="absolute start-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
71	            </div>
72	          </div>
73	
74	          <div className="space-y-1.5">
75	            <label className="text-xs font-bold text-slate-300">Mot de passe</label>
76	            <div className="relative">
77	              <input
78	                type="password"
79	                required
80	                value={password}
81	                onChange={(e) => setPassword(e.target.value)}
82	                placeholder="••••••••"
83	                className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-3 ps-10 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-orange-500 transition-colors"
84	              />
